package com.wordtrail;

import java.sql.SQLException;
import javax.sql.DataSource;
import org.springframework.boot.sql.init.dependency.DependsOnDatabaseInitialization;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.jdbc.core.JdbcTemplate;

/** Completes the H2 fixture after the shared base schemas have been loaded. */
@TestConfiguration(proxyBeanMethods = false)
public class H2TestSchema {
    @Bean @DependsOnDatabaseInitialization
    Object completeH2Schema(DataSource dataSource) throws SQLException {
        try (var connection = dataSource.getConnection()) {
            if (connection.getMetaData().getURL().startsWith("jdbc:h2:mem:")) initialize(dataSource);
        }
        return new Object();
    }

    static void initialize(DataSource source) {
        var db = new JdbcTemplate(source);
        db.execute("ALTER TABLE user_account ADD COLUMN IF NOT EXISTS phone VARCHAR(11) UNIQUE");
        db.execute("ALTER TABLE user_account ADD COLUMN IF NOT EXISTS email VARCHAR_IGNORECASE(254) UNIQUE");
        db.execute("ALTER TABLE user_account ADD COLUMN IF NOT EXISTS email_verified BOOLEAN NOT NULL DEFAULT FALSE");
        db.execute("CREATE TABLE IF NOT EXISTS email_send_guard (id INT PRIMARY KEY)");
        db.execute("MERGE INTO email_send_guard KEY(id) VALUES (1)");
        db.execute("CREATE TABLE IF NOT EXISTS email_send_log (id VARCHAR(36) PRIMARY KEY, email VARCHAR_IGNORECASE(254) NOT NULL, client_ip CHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL)");
        db.execute("CREATE TABLE IF NOT EXISTS email_challenge (email VARCHAR_IGNORECASE(254) PRIMARY KEY, purpose VARCHAR(24) NOT NULL, owner_id BIGINT, session_id VARCHAR(32), token_id VARCHAR(36) NOT NULL, code_hash CHAR(64) NOT NULL, expires_at TIMESTAMP NOT NULL, attempts INT NOT NULL, consumed BOOLEAN NOT NULL)");
        db.execute("CREATE TABLE IF NOT EXISTS email_password_attempt (email VARCHAR_IGNORECASE(254) NOT NULL, client_ip CHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL)");
        db.execute("CREATE TABLE IF NOT EXISTS sms_send_guard (id INT PRIMARY KEY)");
        db.execute("MERGE INTO sms_send_guard KEY(id) VALUES (1)");
        db.execute("CREATE TABLE IF NOT EXISTS sms_send_log (phone VARCHAR(11) NOT NULL, client_ip VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL)");
        db.execute("CREATE TABLE IF NOT EXISTS auth_password_attempt (phone VARCHAR(11) NOT NULL, client_ip VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL)");
        db.execute("CREATE TABLE IF NOT EXISTS sms_challenge (phone VARCHAR(11) PRIMARY KEY, purpose VARCHAR(24) NOT NULL, owner_id BIGINT, session_id VARCHAR(32), expires_at TIMESTAMP NOT NULL, attempts INT NOT NULL, consumed BOOLEAN NOT NULL)");
        db.execute("CREATE TABLE IF NOT EXISTS word_form (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, word_id BIGINT NOT NULL REFERENCES word(id), form VARCHAR(255) NOT NULL, form_type VARCHAR(32) NOT NULL, UNIQUE(word_id,form,form_type))");
        db.execute("CREATE TABLE IF NOT EXISTS word_confusable_pair (word_id_a BIGINT NOT NULL REFERENCES word(id), word_id_b BIGINT NOT NULL REFERENCES word(id), source VARCHAR(64) NOT NULL, similarity_score DECIMAL(10,8) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(word_id_a,word_id_b))");
        db.execute("CREATE TABLE IF NOT EXISTS sentence_tag (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category VARCHAR(32) NOT NULL, name VARCHAR(100) NOT NULL UNIQUE)");
        db.execute("CREATE TABLE IF NOT EXISTS sentence_tag_relation (sentence_id BIGINT NOT NULL REFERENCES sentence_question(id), tag_id BIGINT NOT NULL REFERENCES sentence_tag(id), PRIMARY KEY(sentence_id,tag_id))");
        db.execute("CREATE TABLE IF NOT EXISTS user_sentence_learning (user_id BIGINT NOT NULL REFERENCES user_account(id), sentence_id BIGINT NOT NULL REFERENCES sentence_question(id), added_at TIMESTAMP(3) NOT NULL, PRIMARY KEY(user_id,sentence_id))");
        db.execute("CREATE TABLE IF NOT EXISTS sentence_translation_record (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES user_account(id), sentence_id BIGINT NOT NULL REFERENCES sentence_question(id), translation VARCHAR(2000) NOT NULL, request_id VARCHAR(64) NOT NULL, created_at TIMESTAMP(3) NOT NULL, UNIQUE(user_id,request_id), UNIQUE(id,user_id,sentence_id))");
        // The committed base fixture predates retirement of sentence_translation_attempt.
        var oldConstraints = db.queryForList("SELECT DISTINCT constraint_name FROM information_schema.referential_constraints WHERE constraint_schema='PUBLIC' AND unique_constraint_name IN (SELECT constraint_name FROM information_schema.table_constraints WHERE table_schema='PUBLIC' AND table_name='SENTENCE_TRANSLATION_ATTEMPT')", String.class);
        for (String constraint : oldConstraints) {
            var table = db.queryForObject("SELECT table_name FROM information_schema.table_constraints WHERE constraint_schema='PUBLIC' AND constraint_name=?", String.class, constraint);
            if ("USER_SENTENCE_NOTE".equals(table)) db.execute("ALTER TABLE user_sentence_note DROP CONSTRAINT \"" + constraint.replace("\"", "\"\"") + "\"");
        }
        db.execute("ALTER TABLE user_sentence_note ADD CONSTRAINT IF NOT EXISTS fk_sentence_note_record FOREIGN KEY(attempt_id,user_id,sentence_id) REFERENCES sentence_translation_record(id,user_id,sentence_id)");
    }
}
